<?php
namespace LaraSelector;
use Illuminate\Foundation\Http\Middleware\VerifyCsrfToken; use Illuminate\Support\ServiceProvider; use Illuminate\View\Compilers\BladeCompiler; use LaraSelector\Http\LaraSelectorController;
final class LaraSelectorServiceProvider extends ServiceProvider { public function register():void{$this->mergeConfigFrom(__DIR__.'/../config/laraselector.php','laraselector');$this->app->singleton(Activation::class,fn($a)=>new Activation($a));$this->app->singleton(LaraSelectorToken::class,fn($a)=>new LaraSelectorToken($a['config']->get('laraselector'),(string)$a['config']->get('app.key')));$this->app->singleton(PhpSourceNavigator::class);$this->app->extend('blade.compiler',fn(BladeCompiler $c,$a)=>new InstrumentingLaraSelectorCompiler($a['files'],(string)config('view.compiled'),$a[LaraSelectorToken::class]));} public function boot():void{$this->publishes([__DIR__.'/../config/laraselector.php'=>config_path('laraselector.php')],'laraselector-config');$this->app['router']->middleware('web')->withoutMiddleware(VerifyCsrfToken::class)->prefix('__laraselector')->group(function(){$this->app['router']->get('capabilities',[LaraSelectorController::class,'capabilities']);$this->app['router']->post('handshake',[LaraSelectorController::class,'handshake']);$this->app['router']->post('resolve',[LaraSelectorController::class,'resolve']);});}}
